var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
var p=UnityEngine.Object.FindFirstObjectByType<IndianOceanAssets.ShooterSurvival.PlayerScript>();
var end=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.CompareTag("GameEndTriggerTag")).ToArray();
var enemies=UnityEngine.Object.FindObjectsByType<IndianOceanAssets.ShooterSurvival.EnemyEventController>(UnityEngine.FindObjectsSortMode.None);
return new{run=IndianOceanAssets.ShooterSurvival.TimeManager.isGameRunning,position=p.transform.position.ToString("F2"),hp=p.currentHealth,choices=UnityEngine.Object.FindObjectsByType<IndianOceanAssets.ShooterSurvival.BonusWallChoicePair>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Count(b=>b.Selected!=null),endTriggers=end.Select(t=>new{name=t.name,position=t.position.ToString(),active=t.gameObject.activeInHierarchy,colliders=t.GetComponents<Collider>().Count(c=>c.enabled)}).ToArray(),activeAttackFacing=enemies.Where(e=>e.RuntimeState==IndianOceanAssets.ShooterSurvival.EnemyEventRuntimeState.Attacking).Select(e=>new{id=e.name,angle=Vector3.Angle(e.GetComponentInChildren<Animator>().transform.forward,Vector3.ProjectOnPlane(p.transform.position-e.transform.position,Vector3.up))}).ToArray(),helpers=UnityEngine.Object.FindObjectsByType<IndianOceanAssets.ShooterSurvival.ExtraHelpBuffScript>(UnityEngine.FindObjectsSortMode.None).Select(h=>new{type=h.helpType.ToString(),pos=h.transform.position.ToString(),shots=h.GetComponentsInChildren<IndianOceanAssets.ShooterSurvival.WeaponScript>().Sum(w=>w.TotalProjectilesSpawned)}).ToArray()};
